class Article{const Article({required this.id,required this.title,required this.summary,required this.species,required this.tags,required this.readingMinutes,required this.reviewStatus,required this.safetyLevel,required this.blocks,this.reviewer,this.reviewedAt,this.updatedAt=''});final String id,title,summary,reviewStatus,safetyLevel,updatedAt;final List<String> species,tags;final int readingMinutes;final String? reviewer,reviewedAt;final List<Map<String,dynamic>> blocks;factory Article.fromMap(Map<String,dynamic> m)=>Article(id:m['id'] as String,title:m['title'] as String,summary:m['summary'] as String? ?? '',species:(m['species'] as List? ?? []).map((e)=>e.toString()).toList(),tags:(m['tags'] as List? ?? []).map((e)=>e.toString()).toList(),readingMinutes:m['reading_minutes'] as int? ?? 1,reviewStatus:m['review_status'] as String? ?? 'editorial_review_required',reviewer:m['reviewer'] as String?,reviewedAt:m['reviewed_at'] as String?,safetyLevel:m['safety_level'] as String? ?? 'general',updatedAt:m['updated_at'] as String? ?? '',blocks:(m['body_blocks'] as List? ?? []).whereType<Map>().map((e)=>Map<String,dynamic>.from(e)).toList());}
